import{z as p,x as A,o as t,c as L,q as n,j as o,D as l,d as r,s,S as E,b as e}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"MLIR 多层 IR","description":"","frontmatter":{"title":"MLIR 多层 IR","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/mlir.md","filePath":"cs/mlir.md","lastUpdated":1791063341000}'),d={name:"cs/mlir.md"};function B(m,a,I,M,c,R){const i=A("Mermaid");return t(),L("div",null,[a[2]||(a[2]=n('<h1 id="mlir-多层-ir" tabindex="-1">MLIR 多层 IR <a class="header-anchor" href="#mlir-多层-ir" aria-label="Permalink to &quot;MLIR 多层 IR&quot;">​</a></h1><div class="epigraph"><p>同一框架里并存多种方言：张量、循环、LLVM。下降是方言到方言的合法变换，而不是只在一种三地址 IR 上打遍。</p><footer>—— 据 Lattner et al., MLIR: Scaling Compiler Infrastructure for Domain Specific Computation；对照龙书单层 IR 与[目标描述](/cs/target-description) 整理</footer></div><p>上一课<a href="/cs/wasm-target">Wasm</a> 是一个后端方言的归宿。缺口是<strong>多层</strong>：MLIR 让编译器基础设施服务 DSL 与硬件，而不把一切立刻降到 LLVM IR。本课钉方言与 lowering，DSL 下一课。不把神经网络训练当本栏正文——可点名张量方言存在，细节归大模型栏。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>龙书一条管道：源 → 三地址 → 机器。DSL 与加速器要在高层次做变换（融合、布局）。过早降到 LLVM 丢失结构。MLIR：op+类型在方言里，pass 管 lowering。缺口是<strong>这一架构</strong>，不是 Wasm 验证。</p><p><span class="marginnote">直觉类比：过早降到 LLVM 像把菜谱先剁成肉末再想改刀工——「这是矩阵乘、这是一个循环带」的结构一旦翻译掉，就再也拼不回来。高层次方言让融合、布局这类大刀阔斧的变换发生在结构还完整的时候。</span></p><p>与多面体：affine 方言承接 SCoP。</p><h3 id="mlir-不是「又一个-llvm」" tabindex="-1">MLIR 不是「又一个 LLVM」 <a class="header-anchor" href="#mlir-不是「又一个-llvm」" aria-label="Permalink to &quot;MLIR 不是「又一个 LLVM」&quot;">​</a></h3><p>LLVM IR 是其方言之一。MLIR 是建 IR 的系统。不要把两者当同一文件格式。</p><p><span class="marginnote">Lattner 等 MLIR 论文与 LLVM 项目文档。对照 Appel 单 IR。本课不编造 arXiv 号。基础设施视角，不写具体加速器 ISA。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>定义方言（操作语义、验证器）。写 pass：canonicalization、lowering 到下一方言。最终 <code>llvm</code> 方言 → LLVM 模块 → 原有后端。</p><p><span class="marginnote">术语翻译：「方言」就是一套自定义的操作码加类型词汇表——给每个领域发一本自己的词典，词典之间靠 lowering 互译；「下降」就是把高抽象的词逐步翻译成低抽象的词，语义不许变，只许换说法。</span></p>',13)),(t(),o(E,null,{default:l(()=>[s(i,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20DSL%5B%22DSL%20%2F%20%E5%BC%A0%E9%87%8F%E6%96%B9%E8%A8%80%22%5D%20--%3E%20AFF%5B%22%E4%BB%BF%E5%B0%84%20%2F%20%E5%BE%AA%E7%8E%AF%22%5D%0A%20%20AFF%20--%3E%20LIR%5B%22LLVM%20%E6%96%B9%E8%A8%80%22%5D%0A%20%20LIR%20--%3E%20BE%5B%22%E6%97%A2%E6%9C%89%E5%90%8E%E7%AB%AF%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[r("与"),e("a",{href:"/cs/tree-pattern-isel"},"树匹配"),r("：在低层仍做选择；高层做图变换。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"类型系统可依方言扩展（与 HM 不同，是编译器 IR 类型）。调试：位置信息跨 lowering 传递，难。不要一层 pass 偷偷改变内存模型而不声明。",-1)),a[6]||(a[6]=e("p",null,[e("span",{class:"marginnote"},"常见误区：初学者容易以为 MLIR 是「机器学习中间表示」，只服务神经网络。实际上 ML 指 Multi-Level（多层），它同样被用于 Fortran（Flang）、硬件方言与传统编译管线——凡是需要自定义 IR 层级的领域都能用。")],-1)),(t(),o(E,null,{default:l(()=>[s(i,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20DEF%5B%22%E5%AE%9A%E4%B9%89%E6%96%B9%E8%A8%80%3A%20op%2B%E7%B1%BB%E5%9E%8B%22%5D%20--%3E%20VER%5B%22%E9%AA%8C%E8%AF%81%E5%99%A8%E6%8B%92%E7%BB%9D%E4%B8%8D%E5%90%88%E6%B3%95%E7%A8%8B%E5%BA%8F%22%5D%0A%20%20VER%20--%3E%20PM%5B%22pass%20%E7%AE%A1%E7%90%86%E5%99%A8%22%5D%0A%20%20PM%20--%3E%20CAN%5B%22%E8%A7%84%E8%8C%83%E5%8C%96%3A%20%E5%8C%96%E7%AE%80%E7%AD%89%E4%BB%B7%E5%BD%A2%E5%BC%8F%22%5D%0A%20%20PM%20--%3E%20LOW%5B%22lowering%3A%20%E6%96%B9%E8%A8%80A%E8%AF%91%E5%88%B0%E6%96%B9%E8%A8%80B%22%5D%0A%20%20CAN%20--%3E%20LOC%5B%22%E4%BD%8D%E7%BD%AE%E4%BF%A1%E6%81%AF%E8%B7%A8%E5%B1%82%E6%90%BA%E5%B8%A6%22%5D%0A%20%20LOW%20--%3E%20LOC%0A"})]),fallback:l(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=n('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写具体 DSL 嵌入语法。后课默认：多层方言下降是现代基础设施。下一课 DSL 与嵌入。</p><p>也不把 MLIR 当 XML。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>MLIR：多方言、逐级 lowering，保住高层次结构。</li><li>LLVM 是终点方言之一，不是唯一 IR。</li><li>服务 DSL 与硬件，不替代源语言类型系统课。</li><li>出处：Lattner et al. MLIR；LLVM 文档；对照龙书管道。</li></ul>',5))])}const f=p(d,[["render",B]]);export{u as __pageData,f as default};
